"""Strict JSON schema validation for the forest-controller wire protocol."""

import re

_ID = re.compile(r'[A-Za-z0-9_.\-]{1,32}')

MAXV = 10 ** 12
MAXP = 10 ** 6
MAXNODE = 47
MAXLINK = 127


class Bad(Exception):
    """Raised for every schema violation; the caller answers {"status":"invalid"}."""


def ident(x):
    if not isinstance(x, str):
        raise Bad('id type')
    if _ID.fullmatch(x) is None:
        raise Bad('id charset')
    return x


def integer(x, lo, hi):
    if type(x) is not int:
        raise Bad('int type')
    if x < lo or x > hi:
        raise Bad('int range')
    return x


def tick(x):
    return integer(x, 0, MAXV)


def rate(x):
    return integer(x, 1, MAXV)


def amount(x):
    return integer(x, 0, MAXV)


def rev(x):
    return integer(x, 0, MAXV)


def node(x):
    return integer(x, 0, MAXNODE)


def link(x):
    return integer(x, 0, MAXLINK)


def boolean(x):
    if type(x) is not bool:
        raise Bad('bool type')
    return x


def pair(x, n=None):
    if not isinstance(x, list) or len(x) != 2:
        raise Bad('pair shape')
    return x


def window(x):
    if not isinstance(x, list) or len(x) != 2:
        raise Bad('window shape')
    s = tick(x[0])
    e = tick(x[1])
    if s >= e:
        raise Bad('window order')
    return s, e


def envelope(x, nlinks=None, check_links=True):
    if not isinstance(x, list):
        raise Bad('envelope type')
    if len(x) > MAXLINK:
        raise Bad('envelope size')
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Bad('envelope entry shape')
        l = link(item[0])
        r = rate(item[1])
        if l in out:
            raise Bad('duplicate link')
        if check_links and nlinks is not None and l >= nlinks:
            raise Bad('link reference')
        out[l] = r
    return out


def keys(req, names):
    if not isinstance(req, dict):
        raise Bad('object expected')
    if set(req.keys()) != set(names):
        raise Bad('field set')
